"""policy.ini (docs/policy.md)."""

import re

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": 0,
           "compress_after": 1, "keep": 5, "keep_days": None}
KEYS = set(BUILTIN)
_NUM = re.compile(r"[0-9]+\Z")
_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")


def _bad(msg):
    raise DataError("policy", f"policy.ini: {msg}")


def _value(key, v):
    if key in ("max_size", "max_age", "keep_days") and v == "off":
        return None
    if key == "max_size":
        m = _SIZE.match(v)
        if not m:
            _bad(f"bad {key}")
        return int(m[1]) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m[2].lower()]
    if key == "max_age":
        m = _DUR.match(v)
        if not m:
            _bad(f"bad {key}")
        return int(m[1]) * {"m": 60, "h": 3600, "d": 86400}[m[2]]  # seconds
    if key == "naming":
        if v not in ("numbered", "dated"):
            _bad("bad naming")
        return v
    if key == "offset":
        m = _OFF.match(v)
        if not m or int(m[2]) > 23 or int(m[3]) > 59:
            _bad("bad offset")
        s = int(m[2]) * 3600 + int(m[3]) * 60
        return -s if m[1] == "-" else s
    if not _NUM.match(v):
        _bad(f"bad {key}")
    n = int(v)
    if key == "compress_after":
        return n
    if n < 1:
        _bad(f"bad {key}")
    return n


def load(path):
    """Returns (defaults dict, {stream: dict of its own settings})."""
    if not path.exists():
        return {}, {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"policy.ini: {e}") from None
    defaults, per = None, {}
    cur = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad("bad section line")
            title = line[1:-1]
            if title == "defaults":
                if defaults is not None:
                    _bad("section twice")
                defaults = cur = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                n = title[7:]
                if n in per:
                    _bad("section twice")
                per[n] = cur = {}
            else:
                _bad("unknown section")
            continue
        if cur is None or "=" not in line:
            _bad("bad line")
        k, v = (s.strip() for s in line.split("=", 1))
        if k not in KEYS:
            _bad("unknown key")
        if k in cur:
            _bad("key twice")
        cur[k] = _value(k, v)
    return defaults or {}, per


def settings(defaults, per, name):
    s = dict(BUILTIN)
    s.update(defaults)
    s.update(per.get(name, {}))
    return s
