"""rotate (docs/rotate.md)."""

import gzip
import os
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import policy as policy_mod
from logkeep import state as state_mod
from logkeep import streams
from logkeep.errors import DataError, Refused

_TIME = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})(?:\.([0-9]+))?"
                   r"(Z|[+-][0-9]{2}(?::?[0-9]{2})?)\Z")
_LEGACY = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2}) ([0-9]{2}):([0-9]{2}):([0-9]{2})\Z")
_DAY = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})")


def parse_time(text, legacy=True):
    """A datetime (aware) or None."""
    if not isinstance(text, str):
        return None
    try:
        m = _LEGACY.match(text) if legacy else None
        if m:
            y, mo, d, h, mi, s = map(int, m.groups())
            return datetime(y, mo, d, h, mi, s, tzinfo=timezone.utc)
        m = _TIME.match(text)
        if not m:
            return None
        y, mo, d, h, mi, s = map(int, m.groups()[:6])
        us = int((m[7] + "000000")[:6]) if m[7] else 0
        z = m[8]
        if z == "Z":
            tz = timezone.utc
        else:
            digits = z[1:].replace(":", "")
            off = int(digits[:2]) * 3600 + (int(digits[2:4]) * 60 if len(digits) > 2 else 0)
            if int(digits[:2]) > 23 or (len(digits) > 2 and int(digits[2:4]) > 59):
                return None
            tz = timezone(timedelta(seconds=-off if z[0] == "-" else off))
        return datetime(y, mo, d, h, mi, s, us, tzinfo=tz)
    except ValueError:
        return None


class Arc:
    def __init__(self, name, key, gz):
        self.old = name
        self.key = key
        self.gz = gz
        self.new = False
        self.time = None  # raw string in state
        self.removed = False


def _archives(ctx, name, naming):
    d = streams.logs_dir(ctx.data)
    out, seen = [], {}
    if not d.is_dir():
        return out
    prefix = f"{name}.log."
    for p in d.iterdir():
        fn = p.name
        if not fn.startswith(prefix) or not p.is_file():
            continue
        rest = fn[len(prefix):]
        gz = rest.endswith(".gz")
        if gz:
            rest = rest[:-3]
        key = None
        if naming == "numbered":
            if re.fullmatch(r"[1-9][0-9]*", rest):
                key = (int(rest),)
        else:
            m = re.fullmatch(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([1-9][0-9]*))?", rest)
            if m:
                try:
                    day = date.fromisoformat(m[1])
                except ValueError:
                    day = None
                if day and (m[2] is None or int(m[2]) >= 2):
                    key = (day, int(m[2]) if m[2] else 1)
        if key is None:
            continue
        if key in seen:
            raise DataError("archives", f"{name}: two archives in the same place: {rest}")
        seen[key] = 1
        out.append(Arc(fn, key, gz))
    return out


def _first_time(path):
    try:
        with open(path, "rb") as f:
            line = f.readline()
        text = line.decode("utf-8").rstrip("\r\n")
    except (OSError, UnicodeDecodeError):
        return None
    return parse_time(text.split(" ", 1)[0], legacy=False)


def _validate_state(entry):
    if "opened" in entry and parse_time(entry["opened"]) is None:
        raise DataError("state", "bad opened")
    if "archives" in entry:
        a = entry["archives"]
        if not isinstance(a, dict):
            raise DataError("state", "archives is not an object")
        for v in a.values():
            if parse_time(v) is None:
                raise DataError("state", "bad archive time")
    if "rotations" in entry:
        r = entry["rotations"]
        if isinstance(r, bool) or not isinstance(r, int) or r < 0:
            raise DataError("state", "bad rotations")


def run(ctx, names, dry_run, force):
    defaults, per = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    existing = set(per) | set(streams.active(ctx.data))
    for n in existing:
        e = doc["streams"].get(n)
        if e is not None:
            _validate_state(e)
    if names:
        for n in sorted(set(names)):
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        todo = sorted(set(names))
    else:
        todo = sorted(existing)

    plans = []
    for n in todo:
        s = policy_mod.settings(defaults, per, n)
        entry = doc["streams"].get(n, {})
        plans.append(_plan(ctx, n, s, entry, force))

    lines, nrot, nrem, ncomp = [], 0, 0, 0
    for p in plans:
        lines.append(f"{p['name']}: {p['what']}")
        for a in p["kept"]:
            if a.new:
                lines.append(f"  new {a.final}")
            elif a.final != a.old:
                lines.append(f"  {a.final} <- {a.old}")
            else:
                lines.append(f"  {a.final}")
        for a in p["removed"]:
            lines.append(f"  remove {a.old}")
        nrot += p["rotated"]
        nrem += len(p["removed"])
        ncomp += sum(1 for a in p["kept"] if a.compress)
    lines.append(f"{nrot} rotated, {nrem} removed, {ncomp} compressed")
    if dry_run:
        lines.append("dry run: nothing written")
        return lines
    _apply(ctx, plans)
    for p in plans:
        doc["streams"][p["name"]] = p["entry"]
    state_mod.save(ctx.state_path, doc)
    return lines


def _plan(ctx, name, s, entry, force):
    log = streams.log_path(ctx.data, name)
    now = ctx.now
    if not log.is_file():
        what = "no log"
    else:
        size = log.stat().st_size
        if size == 0:
            what = "empty"
        elif force:
            what = "rotate (forced)"
        elif s["max_size"] is not None and size >= s["max_size"]:
            what = "rotate (size)"
        else:
            what = "not due"
            if s["max_age"] is not None:
                opened = parse_time(entry["opened"]) if "opened" in entry else _first_time(log)
                if opened is not None and (now - opened).total_seconds() >= s["max_age"]:
                    what = "rotate (age)"
    rotated = what.startswith("rotate")
    naming = s["naming"]
    arcs = _archives(ctx, name, naming)
    times = entry.get("archives", {})
    for a in arcs:
        a.time = times.get(a.old)
    arcs.sort(key=lambda a: a.key, reverse=(naming == "dated"))
    if naming == "dated":
        pass  # newest first
    if rotated:
        if naming == "numbered":
            fn = f"{name}.log.1"
            key = (0,)
        else:
            day = now.astimezone(timezone(timedelta(seconds=s["offset"]))).date()
            used = [a.key[1] for a in arcs if a.key[0] == day]
            if not used:
                k = 1
            else:
                k = 2
                while k in used:
                    k += 1
            fn = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
            key = (day, k)
        new = Arc(fn, key, False)
        new.new = True
        new.time = ctx.stamp
        arcs.insert(0, new)
    # arcs newest first; retention
    kept, removed = [], []
    for pos, a in enumerate(arcs, 1):
        gone = pos > s["keep"]
        if not gone and s["keep_days"] is not None and a.time is not None:
            t = parse_time(a.time)
            if (now - t) >= timedelta(days=s["keep_days"]):
                gone = True
        (removed if gone else kept).append(a)
    for i, a in enumerate(kept, 1):
        a.compress = (i > s["compress_after"]) and not a.gz
        gz = a.gz or a.compress
        if naming == "numbered":
            base = f"{name}.log.{i}"
        else:
            base = a.old[:-3] if a.old.endswith(".gz") else a.old
        a.final = base + (".gz" if gz else "")
    if rotated and not entry.get("archives") is None or True:
        pass
    new_entry = {}
    if rotated:
        new_entry["opened"] = ctx.stamp
    elif "opened" in entry:
        new_entry["opened"] = entry["opened"]
    new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
    new_entry["archives"] = {a.final: a.time for a in kept if a.time is not None}
    return {"name": name, "what": what, "rotated": 1 if rotated else 0, "kept": kept,
            "removed": removed, "entry": new_entry}


def _apply(ctx, plans):
    d = streams.logs_dir(ctx.data)
    jobs = []  # (tmp path, final path, compress)
    n = 0
    for p in plans:
        for a in p["removed"]:
            (d / a.old).unlink()
        for a in p["kept"]:
            if a.new:
                continue
            if a.final != a.old:
                n += 1
                tmp = d / f".logkeep-rotate-{os.getpid()}-{n}.tmp"
                os.rename(d / a.old, tmp)
                jobs.append((tmp, d / a.final, a.compress))
        for a in p["kept"]:
            if a.new:
                n += 1
                log = streams.log_path(ctx.data, p["name"])
                tmp = d / f".logkeep-rotate-{os.getpid()}-{n}.tmp"
                os.rename(log, tmp)
                log.write_bytes(b"")
                jobs.append((tmp, d / a.final, a.compress))
    for tmp, final, comp in jobs:
        if comp:
            final.write_bytes(gzip.compress(tmp.read_bytes(), mtime=0))
            tmp.unlink()
        else:
            os.rename(tmp, final)
